// Offline icon library (Lucide, ISC — see ./generated/LUCIDE_LICENSE.txt).
// Data is generated by `npm run icons:build` into ./generated/lucide-icons.json and loaded lazily
// (its own code-split chunk). Every icon is a list of SVG path `d` strings in a 24×24 viewBox,
// meant to be drawn with Konva.Path as strokes: no fill, stroke-width 2 (at 24px), round caps/joins.

export interface IconDef {
  name: string;
  d: string[];
  tags: string[];
}

export const ICON_VIEWBOX = 24;

/** How Lucide icons must be rendered (scale strokeWidth by size / ICON_VIEWBOX). */
export const ICON_STROKE = { fill: 'none', strokeWidth: 2, lineCap: 'round', lineJoin: 'round' } as const;

interface IconJson {
  version: string;
  license: string;
  source: string;
  viewBox: number;
  icons: Record<string, { d: string[]; tags: string[] }>;
}

let registry: Map<string, IconDef> | null = null;
let list: IconDef[] = [];
let loading: Promise<void> | null = null;
let meta: { version: string; source: string; license: string } | null = null;

export function loadIcons(): Promise<void> {
  if (registry) return Promise.resolve();
  loading ??= import('./generated/lucide-icons.json')
    .then((mod) => {
      const data = ((mod as { default?: unknown }).default ?? mod) as IconJson;
      const map = new Map<string, IconDef>();
      for (const [name, v] of Object.entries(data.icons)) map.set(name, { name, d: v.d, tags: v.tags });
      list = [...map.values()];
      meta = { version: data.version, source: data.source, license: data.license };
      registry = map;
    })
    .catch((err: unknown) => {
      loading = null;
      throw err;
    });
  return loading;
}

export function iconsLoaded(): boolean {
  return registry !== null;
}

/** Source/version/license of the loaded set, or null before load. */
export function iconSetInfo(): { version: string; source: string; license: string } | null {
  return meta;
}

/** All icons (sorted by name); empty before load. */
export function listIcons(): readonly IconDef[] {
  return list;
}

export function getIcon(name: string): IconDef | null {
  return registry?.get(name.trim().toLowerCase()) ?? null;
}

// ---------------------------------------------------------------- search

const S_NAME_EXACT = 1000;
const S_NAME_PREFIX = 800;
const S_NAME_CONTAINS = 600;
const S_TAG_EXACT = 400;
const S_TAG_CONTAINS = 200;

const normalize = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

/** Score a single token against an icon (0 = no match). */
function tokenScore(icon: IconDef, token: string): number {
  const name = icon.name;
  if (name === token) return S_NAME_EXACT;
  const parts = name.split('-');
  if (name.startsWith(token)) return S_NAME_PREFIX;
  if (parts.includes(token)) return S_NAME_CONTAINS + 50; // whole word inside the name
  if (name.includes(token)) return S_NAME_CONTAINS;
  let best = 0;
  for (const tag of icon.tags) {
    const t = tag.toLowerCase();
    if (t === token) return S_TAG_EXACT;
    if (best < S_TAG_CONTAINS && t.includes(token)) best = S_TAG_CONTAINS;
  }
  return best;
}

interface Scored {
  icon: IconDef;
  score: number;
}

function scoreAll(query: string): Scored[] {
  const q = normalize(query);
  if (!q || !registry) return [];
  const tokens = q.split(' ');
  const joined = tokens.join('-');
  const out: Scored[] = [];
  for (const icon of list) {
    let score: number;
    if (tokens.length === 1) {
      score = tokenScore(icon, joined);
    } else {
      // Whole phrase as a hyphenated name ("trending up" -> trending-up) beats per-word matches.
      const phrase =
        icon.name === joined
          ? S_NAME_EXACT * 2
          : icon.name.startsWith(joined)
            ? S_NAME_PREFIX * 2
            : icon.name.includes(joined)
              ? S_NAME_CONTAINS * 2
              : icon.tags.some((t) => normalize(t) === q)
                ? S_TAG_EXACT * 2
                : 0;
      let sum = 0;
      let all = true;
      for (const t of tokens) {
        const s = tokenScore(icon, t);
        if (!s) all = false;
        sum += s;
      }
      // Require every word to match; phrase hits always qualify.
      score = phrase ? phrase + sum : all ? sum / tokens.length : 0;
    }
    if (score > 0) out.push({ icon, score });
  }
  out.sort((a, b) => b.score - a.score || a.icon.name.length - b.icon.name.length || a.icon.name.localeCompare(b.icon.name));
  return out;
}

/**
 * Case-insensitive search. Ranking: exact name > name prefix > name contains > tag exact > tag contains.
 * Multi-word queries match the hyphenated name as a phrase or require every word to match.
 */
export function searchIcons(query: string, limit = 50): IconDef[] {
  return scoreAll(query)
    .slice(0, Math.max(0, limit))
    .map((s) => s.icon);
}

