const singular = (w: string) =>
  w.length > 4 && w.endsWith('ies') ? `${w.slice(0, -3)}y` : w.length > 3 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w;

function fromSynonyms(key: string): IconDef | null {
  const list = ICON_SYNONYMS[key] ?? ICON_SYNONYMS[key.replace(/ /g, '_')];
  if (!list) return null;
  for (const n of list) {
    const icon = registry?.get(n);
    if (icon) return icon;
  }
  return null;
}

/** Minimum score for a fuzzy search hit to count as a "reasonable" icon. */
const MIN_SCORE = S_TAG_EXACT;

/**
 * Best single icon for AI-provided keywords like ['clock'], ['team', 'meeting'], ['growth'].
 * Earlier keywords win. Order per keyword: exact icon name → synonym map → singular form →
 * then a combined/ per-keyword search above a quality threshold. Returns null if nothing fits.
 */
export function iconForKeywords(keywords: string[]): IconDef | null {
  if (!registry) return null;
  const kws = keywords.map(normalize).filter(Boolean);
  if (!kws.length) return null;

  for (const k of kws) {
    const hyphen = k.replace(/ /g, '-');
    const direct = registry.get(hyphen) ?? fromSynonyms(k);
    if (direct) return direct;
    const s = singular(k);
    if (s !== k) {
      const viaSingular = registry.get(s) ?? fromSynonyms(s);
      if (viaSingular) return viaSingular;
    }
    // Multi-word keyword: try each word's synonym/name.
    if (k.includes(' ')) {
      for (const w of k.split(' ')) {
        const hit = registry.get(w) ?? fromSynonyms(w) ?? fromSynonyms(singular(w));
        if (hit && w.length > 2) return hit;
      }
    }
  }

  // Fuzzy: all keywords together first, then each keyword (earlier keywords preferred on ties).
  const queries = kws.length > 1 ? [kws.join(' '), ...kws] : kws;
  let best: Scored | null = null;
  for (const q of queries) {
    const top = scoreAll(q)[0];
    if (top && top.score >= MIN_SCORE && (!best || top.score > best.score)) best = top;
  }
  return best?.icon ?? null;
}
